local Yielders          = CS.Engine.Lib.Yielders
------------ import ------------

------------ define ------------
local SafeUnpack                             = SafeUnpack
local PVPArenaAgainstHeadSingleNodePath      = "Game.UI.PVPArena.PVPArenaAgainstHeadSingleNode"
local PVPArenaMatchChartAgainstStateNodePath = "Game.UI.PVPArena.PVPArenaMatchChartAgainstStateNode"

local WaitForSeconds = Yielders.GetWaitForSeconds(1.5)
------------ define ------------

function PVPArenaFinalMatchChart:__init()
end

