function PVPArenaFinalMatchChart:RefreshUI()

    local seasonFlag = pvpArenaComponent:GetSeasonFlag()
    if  seasonFlag == Constants.PVPArenaSeasonFullStatus.Quiz or
        seasonFlag == Constants.PVPArenaSeasonFullStatus.Notice or
        seasonFlag == Constants.PVPArenaSeasonFullStatus.Group then
        return
    end

    local lineLayers   = {self.LineLayer1, self.LineLayer2, self.LineLayer3}
    local headLayers   = {self.HeadLayer1, self.HeadLayer2, self.HeadLayer3, self.HeadLayer4}

    local pvpArenaDojo      = pvpArenaComponent:GetPVPArenaDojo()
    local pvpArenaEntryDojo = pvpArenaComponent:GetPVPArenaEntryDojo()
    local allWheelScope     = pvpArenaComponent:GetAllWheelScope()
    local groupWheelCount   = pvpArenaComponent:GetGroupWheelCount()
    local finalWheelCount   = pvpArenaComponent:GetFinalWheelCount()
    local map               = checkTable(pvpArenaDojo.map)
    local matcherInfo       = checkTable(pvpArenaDojo.matcherInfo)
    local isInBattle        = checkNumber(pvpArenaEntryDojo.battleStatus) == Constants.PVPArenaBattleStatus.InBattle
    local winPlayerId2win   = PVPArenaUtils.CreateWinPlayerId2win(map, pvpArenaComponent:GetCurWheel(), allWheelScope)

    local displayWheelCount = finalWheelCount + 1
    for wheel = 1, displayWheelCount do
        ---@type UnityEngine.RectTransform
        local headLayer    = headLayers[wheel]
        --- 最后一轮是nil
        ---@type UnityEngine.RectTransform
        local lineLayer    = lineLayers[wheel]

        local isDisplayWheel = wheel == displayWheelCount
        local isRealLastWheel = wheel == finalWheelCount
        local oneWheelGroupScope = allWheelScope[wheel + groupWheelCount]
        local leftNum, rightNum  = SafeUnpack(oneWheelGroupScope)
        for position = leftNum, rightNum, 2 do
            local oneMatchChartData = PVPArenaUtils.CreateOneMatchChartData(position, wheel, isInBattle, map, matcherInfo)
            local index = position - leftNum
            local headNode = headLayer:GetChild(index)
            self:RefreshAgainstHeadSingleNode(headNode.gameObject, oneMatchChartData, index, isDisplayWheel)

            --- 展示轮只需展示冠军头像
            if not isDisplayWheel then
                index = index + 1
                headNode = headLayer:GetChild(index)
                self:RefreshAgainstHeadSingleNode(headNode.gameObject, oneMatchChartData, index, isDisplayWheel)

                local lineNodeIdx = math.floor(index / 2)
                local lineNode    = lineLayer:GetChild(lineNodeIdx)
                self:RefreshAgainstStateNode(lineNode.gameObject, oneMatchChartData, winPlayerId2win, isRealLastWheel, wheel, lineNodeIdx)
            end
        end

    end

    self:CreateAgainstStateCo()

end
---------------------------------------------------
--- ui logic end --
