---RefreshAgainstHeadSingleNode
---@param gameObject UnityEngine.GameObject
---@param oneMatchChartData table
---@param index number 下标
---@param isLastWheel boolean 是否是最后一轮
function PVPArenaFinalMatchChart:RefreshAgainstHeadSingleNode(gameObject, oneMatchChartData, index, isLastWheel)
    ---@type PVPArenaAgainstHeadSingleNode
    local env = CfUtils.GetLuaScr(gameObject, PVPArenaAgainstHeadSingleNodePath)
    if not isNull(env) then

        env:RefreshUI(oneMatchChartData, isLastWheel, index, self.playerId)
    end
end

function PVPArenaFinalMatchChart:RefreshAgainstStateNode(gameObject, oneMatchChartData, winPlayerId2win, isRealLastWheel, wheel, lineNodeIdx)
    ---@type PVPArenaMatchChartAgainstStateNode
    local env  = CfUtils.GetLuaScr(gameObject, PVPArenaMatchChartAgainstStateNodePath)
    if not isNull(env) then
        env:SetWheel(wheel)
        env:SetPlayerId2Group(self.playerId2Group)
        env:RefreshUI(oneMatchChartData, winPlayerId2win, true, isRealLastWheel, lineNodeIdx)
    end
end

function PVPArenaFinalMatchChart:CreateAgainstStateCo()
    if self.againstStateCo then return end
    local finalWheelCount   = pvpArenaComponent:GetFinalWheelCount()
    self.againstStateCo = cs_coroutine.start(function()
        local PVPArenaMatchChartPlayEffect = Constants.EventNames.PVPArenaMatchChartPlayEffect
        local wheel = 1
        while true do
            Events.Broadcast(PVPArenaMatchChartPlayEffect, wheel)
            cs_coroutine.yield_return(WaitForSeconds)
            wheel = wheel == finalWheelCount and 1 or wheel + 1
        end
    end)
end

function PVPArenaFinalMatchChart:RemoveAgainstStateCo()
    if not isNull(self.againstStateCo) then
        cs_coroutine.stop(self.againstStateCo)
        self.againstStateCo = nil
    end
end

